* var z1 = new Complex128( 5.0, 3.0 );
* var z2 = new Complex128( -2.0, 1.0 );
*
* var out = mul( z1, z2 );
* // returns <Complex128>[ -13.0, -1.0 ]
*/
function mul( z1, z2 ) {
	var re1 = real( z1 );
	var re2 = real( z2 );
	var im1 = imag( z1 );
	var im2 = imag( z2 );
	var re = (re1*re2) - (im1*im2);
	var im = (re1*im2) + (im1*re2);
	return new Complex128( re, im );
}


